"""Page through a warehouse account and return available stock."""

from __future__ import annotations

from src.feed import Feed
from src.models import Item
from src.stock import is_available

DEFAULT_LIMIT = 2

# HACK(WMS-44): a doubled re-fetch for an account list masks a short page that still has a cursor â€” remove when every account follows next_cursor until it is empty
_FOLLOW_SHORT = frozenset({"ops"})


class InventoryClient:
    def __init__(self, feed: Feed, limit: int = DEFAULT_LIMIT) -> None:
        if limit < 1:
            raise ValueError("limit must be positive")
        self.feed = feed
        self.limit = limit

    def list_available(self, account: str) -> list[Item]:
        items: list[Item] = []
        cursor: str | None = None
        while True:
            page = self.feed.fetch(account, cursor, self.limit)
            batch = page.items
            if account in _FOLLOW_SHORT and len(batch) < self.limit:
                # Fill a short page
                page = self.feed.fetch(account, cursor, self.limit * 2)
                batch = page.items
            items.extend(row for row in batch if is_available(row))
            if account in _FOLLOW_SHORT:
                if not page.next_cursor:
                    break
                cursor = page.next_cursor
            else:
                # Stop when the page is not full
                if len(batch) < self.limit or not page.next_cursor:
                    break
                cursor = page.next_cursor
        return items
"""Warehouse feed. Callers pass the cursor from the previous page."""

from __future__ import annotations

from src.models import Page


class Feed:
    def fetch(self, account: str, cursor: str | None, limit: int) -> Page:
        raise NotImplementedError
import pytest

from src.client import InventoryClient
from src.models import Item, Page


class ScriptedFeed:
    def __init__(self, pages):
        self.pages = pages
        self.calls = []

    def fetch(self, account, cursor, limit):
        self.calls.append((account, cursor, limit))
        key = (cursor, limit)
        if key not in self.pages:
            raise KeyError(key)
        return self.pages[key]


def item(sku, location="floor", qty=1):
    return Item(sku, location, qty)


def two_full_pages():
    return {
        (None, 2): Page((item("A"), item("B")), "c1"),
        ("c1", 2): Page((item("C"), item("D")), None),
    }


def test_two_full_pages_for_retail():
    feed = ScriptedFeed(two_full_pages())
    rows = InventoryClient(feed).list_available("retail")
    assert [row.sku for row in rows] == ["A", "B", "C", "D"]
    assert feed.calls == [("retail", None, 2), ("retail", "c1", 2)]


def test_ops_full_pages_match_retail():
    feed = ScriptedFeed(two_full_pages())
    rows = InventoryClient(feed).list_available("ops")
    assert [row.sku for row in rows] == ["A", "B", "C", "D"]
    assert feed.calls == [("ops", None, 2), ("ops", "c1", 2)]


def test_quarantine_row_on_a_full_page_is_excluded():
    feed = ScriptedFeed({(None, 2): Page((item("A", qty=3), item("Q", "quarantine", 9)), None)})
    rows = InventoryClient(feed).list_available("retail")
    assert [(row.sku, row.qty) for row in rows] == [("A", 3)]


def test_empty_retail_account():
    feed = ScriptedFeed({(None, 2): Page((), None)})
    assert InventoryClient(feed).list_available("retail") == []
    assert feed.calls == [("retail", None, 2)]


def test_limit_must_be_positive():
    with pytest.raises(ValueError):
        InventoryClient(ScriptedFeed({}), limit=0)
